/** Base64-inlined copy of reference/screenshots/geode-01.png (resized to 1600px wide, JPEG q85)
 * so stage 1 works when index.html is opened directly via file:// - loading the PNG by its
 * relative path and drawing it to a canvas (needed for OpenCV.js to read it) taints the canvas
 * under file://, since each local file counts as a different origin there (same issue the
 * block textures had, see js/TextureData.js). The full-resolution original stays in
 * reference/screenshots/ for reference; this smaller copy is plenty for line detection, which
 * downscales further anyway (see js/CalibrationTools.js). */
const PHOTO_DATA = {
	geode01: "data:image/jpeg;base64,",
}
